data class EnrollmentIconData(val color: Int, val imageResource: Int)

fun List<Program>.getEnrollmentIconsData(
    context: Context,
    currentProgram: String?
): List<EnrollmentIconData> {
    val listSize = this.size
    var programCount = 0
    val iconDatas = mutableListOf<EnrollmentIconData>()

    val filteredPrograms = filter { it.uid() != currentProgram }
    for (program in filteredPrograms) {
        programCount++
        if (programCount >= 4 && listSize > 4) {
            break
        } else {
            val color = ColorUtils.getColorFrom(
                program.style().color(),
                ColorUtils.getPrimaryColor(
                    context,
                    ColorUtils.ColorType.PRIMARY
                )
            )
            val imageResource =
                ResourceManager(context)
                    .getObjectStyleDrawableResource(
                        program.style().icon(),
                        R.drawable.ic_default_icon
                    )
            iconDatas.add(EnrollmentIconData(color, imageResource))
        }
    }

    return iconDatas
}

fun List<Program>.addEnrollmentIcons(
    context: Context,
    parent: ComposeView,
    currentProgram: String?
) {
    val listSize = this.size
    val icons = getEnrollmentIconsData(context, currentProgram)
    parent.apply {
        setContent {
            MdcTheme {
                Row(
                    horizontalArrangement = spacedBy(Dp(4f)),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    icons.forEach { icon ->
                        MetadataIcon(
                            metadataIconData = MetadataIconData(
                                programColor = icon.color,
                                iconResource = icon.imageResource,
                                sizeInDp = 24
                            )
                        )
                    }
                    if (listSize > 4) {
                        val otherEnrollmentsCount = getOtherEnrollmentsForTei(listSize)
                        SquareWithNumber(otherEnrollmentsCount)
                    }
                }
            }
        }
    }
}

